template <typename T>
void key_add(uint64_t &h, const T &v) { h = runtime::fnv64(&v, sizeof v, h); }

class Type final : public runtime::PipelineType {
 public:
  const char *name() const override { return "grass"; }
  size_t params_size() const override { return sizeof(Params); }
  size_t event_count() const override { return 0; }
  bool has_update() const override { return false; }
  uint32_t detail_levels() const override { return 4; }
  size_t detail_offset() const override { return offsetof(Params, detail); }
  const float *detail_pixels(int quality) const override {
    static const float k[3][3] = {{256.0f, 256.0f, 64.0f}, {256.0f, 96.0f, 0.0f}, {96.0f, 64.0f, 0.0f}};  // low, medium, high
    return k[quality < 0 ? 0 : quality > 2 ? 2 : quality];
  }
  const runtime::ParamInfo *param_table(size_t &count) const override {
    static const char *const v_species[] = {"dune", "lawn", "meadow", "prairie", "sedge"};
    static const char *const v_season[] = {"winter", "spring", "summer", "fall"};
    static const char *const v_detail[] = {"high", "medium", "low", "mat"};
    static const char *const v_bed[] = {"own", "none"};
    static const char *const v_ground[] = {"soil", "water", "rock", "sand", "path"};
    static const runtime::ParamInfo t[] = {
      {"species", runtime::ParamInfo::kEnum, offsetof(Params, species), true, v_species, 5u, 0.0, 0.0},
      {"season", runtime::ParamInfo::kEnum, offsetof(Params, season), true, v_season, 4u, 0.0, 0.0},
      {"variant", runtime::ParamInfo::kU32, offsetof(Params, variant), true, nullptr, 0u, 0.0, 12.0},
      {"detail", runtime::ParamInfo::kEnum, offsetof(Params, detail), true, v_detail, 4u, 0.0, 0.0},
      {"bed", runtime::ParamInfo::kEnum, offsetof(Params, bed), true, v_bed, 2u, 0.0, 0.0},
      {"cell_q", runtime::ParamInfo::kU32, offsetof(Params, cell_q), true, nullptr, 0u, 0.0, 1000.0},
      {"cell_r", runtime::ParamInfo::kU32, offsetof(Params, cell_r), true, nullptr, 0u, 0.0, 1000.0},
      {"ground", runtime::ParamInfo::kEnum, offsetof(Params, ground), true, v_ground, 5u, 0.0, 0.0},
      {"moisture", runtime::ParamInfo::kF32, offsetof(Params, moisture), true, nullptr, 0u, 0.0, 1.0},
      {"world_seed", runtime::ParamInfo::kU32, offsetof(Params, world_seed), true, nullptr, 0u, 1.0, 1000000.0},
      {"wind_speed", runtime::ParamInfo::kF32, offsetof(Params, wind_speed), true, nullptr, 0u, 0.0, 25.0},
      {"wind_heading", runtime::ParamInfo::kF32, offsetof(Params, wind_heading), true, nullptr, 0u, 0.0, 360.0}};
    count = 12;
    return t;
  }
  bool is_field() const override { return true; }
  bool field_cells(const void *params, const runtime::FieldCell *cells, size_t count, runtime::FieldChoice *out,
                   std::string &error) const override {
    const Params &p = *static_cast<const Params *>(params);
    channels::grass_cell cell_in;
    config_species(static_cast<uint32_t>(p.species), cell_in.genome);
    cell_in.season = static_cast<uint32_t>(p.season);
    cell_in.q = p.cell_q;
    cell_in.r = p.cell_r;
    cell_in.ground = static_cast<uint32_t>(p.ground);
    cell_in.moisture = p.moisture;
    cell_in.seed = p.world_seed;
    channels::grass_choice cell_out;
    for (size_t i = 0; i < count; ++i) {
      cell_in.q = static_cast<decltype(cell_in.q)>(cells[i].q);
      cell_in.r = static_cast<decltype(cell_in.r)>(cells[i].r);
      cell_in.ground = static_cast<decltype(cell_in.ground)>(cells[i].ground);
      cell_in.moisture = static_cast<decltype(cell_in.moisture)>(cells[i].moisture);
      if (!grass_cell::run(cell_in, cell_out, error)) {
        error = "cell (grass_cell): " + error;
        return false;
      }
      runtime::FieldChoice &c = out[i];
      c.present = cell_out.present;
      c.variant = cell_out.variant;
      c.turn = cell_out.turn;
      c.scale = cell_out.scale;
      c.tint[0] = cell_out.tint.x;
      c.tint[1] = cell_out.tint.y;
      c.tint[2] = cell_out.tint.z;
    }
    return true;
  }
  void field_tile_params(const void *params, uint32_t variant, void *out) const override {
    Params t = *static_cast<const Params *>(params);
    t.variant = variant;
    t.cell_q = 0u;
    t.cell_r = 0u;
    t.ground = static_cast<foundry_grass_ground>(0);
    t.moisture = 0x1.19999a0000000p-1f;
    t.world_seed = 1u;
    std::memcpy(out, &t, sizeof t);
  }
  void field_wind(const void *params, float &speed, float &heading) const override {
    const Params &p = *static_cast<const Params *>(params);
    speed = p.wind_speed;
    heading = p.wind_heading;
  }

  const std::vector<runtime::StageInfo> &stages() const override {
    static const std::vector<runtime::StageInfo> s = {{"grass.cell", false}, {"grass.tile", false}};
    return s;
  }

  uint64_t build_key(const void *params) const override {
    const Params &p = *static_cast<const Params *>(params);
    uint64_t h = runtime::fnv64("grass", 5);
    key_add(h, p.species);
    key_add(h, p.season);
    key_add(h, p.variant);
    key_add(h, p.detail);
    key_add(h, p.bed);
    key_add(h, p.cell_q);
    key_add(h, p.cell_r);
    key_add(h, p.ground);
    key_add(h, p.moisture);
    key_add(h, p.world_seed);
    key_add(h, p.wind_speed);
    key_add(h, p.wind_heading);
    return h ? h : 1;
  }

  std::shared_ptr<runtime::Build> build(const void *params, std::string &error) const override {
    return build_impl(params, nullptr, error);
  }

  std::shared_ptr<runtime::Build> build_impl(const void *params, const std::vector<uint8_t> *payload,
                                             std::string &error) const {
    const Params &p = *static_cast<const Params *>(params);
    (void)payload;
    auto b = std::make_shared<Built>();
    const float *clocks = nullptr;
    (void)clocks;
    // cell: grass_cell
    channels::grass_cell cell_in;
    config_species(static_cast<uint32_t>(p.species), cell_in.genome);
    cell_in.season = static_cast<uint32_t>(p.season);
    cell_in.q = p.cell_q;
    cell_in.r = p.cell_r;
    cell_in.ground = static_cast<uint32_t>(p.ground);
    cell_in.moisture = p.moisture;
    cell_in.seed = p.world_seed;
    channels::grass_choice cell_out;
    {
      const auto t0 = std::chrono::steady_clock::now();
      if (!grass_cell::run(cell_in, cell_out, error)) {
        error = "cell (grass_cell): " + error;
        return nullptr;
      }
      b->stage_ms.push_back(ms_since(t0));
    }
    // tile: grass_tile
    channels::grass_spec tile_in;
    config_species(static_cast<uint32_t>(p.species), tile_in.genome);
    tile_in.season = static_cast<uint32_t>(p.season);
    tile_in.variant = p.variant;
    tile_in.detail = static_cast<uint32_t>(p.detail);
    tile_in.bed = static_cast<uint32_t>(p.bed);
    channels::grass_model tile_out;
    {
      const auto t0 = std::chrono::steady_clock::now();
      if (!grass_tile::run(tile_in, tile_out, error)) {
        error = "tile (grass_tile): " + error;
        return nullptr;
      }
      b->stage_ms.push_back(ms_since(t0));
    }
    {
      std::vector<uint8_t> bytes;
      foundry::pack(tile_out, bytes);
      b->model_hash = runtime::fnv64(bytes.data(), bytes.size());
    }
    b->mesh.positions = std::move(tile_out.positions);
    b->mesh.normals = std::move(tile_out.normals);
    b->mesh.colors = std::move(tile_out.colors);
    b->mesh.indices = std::move(tile_out.indices);
    b->mesh.sway = std::move(tile_out.sway);
    const auto &m = b->mesh;
    b->triangles = static_cast<uint32_t>(m.indices.size() / 3);
    uint32_t bones = 1;
    for (size_t i = 0; i < m.bone_a.size(); ++i) bones = std::max(bones, m.bone_a[i] + 1);
    for (size_t i = 0; i < m.bone_b.size(); ++i) bones = std::max(bones, m.bone_b[i] + 1);
    b->bones = bones;
    float top = 0;
    bool finite = true;
    for (const auto &v : m.positions) {
      top = std::max(top, v.y);
      finite = finite && std::isfinite(v.x) && std::isfinite(v.y) && std::isfinite(v.z);
    }
    float r2 = 0;
    for (const auto &v : m.positions) {
      const float dy = v.y - top * 0.5f;
      r2 = std::max(r2, v.x * v.x + dy * dy + v.z * v.z);
    }
    b->height = top;
    b->radius = std::sqrt(r2);
    runtime::terrain_bounds(*b);
    if (!finite) b->problem = "a vertex is not finite";
    else if (m.indices.empty()) b->problem = "the mesh has no triangles";
    else if (*std::max_element(m.indices.begin(), m.indices.end()) >= m.positions.size()) b->problem = "an index is out of range";
    return b;
  }

  std::unique_ptr<runtime::PoseState> bind(const runtime::Build &build) const override {
    const Built &b = static_cast<const Built &>(build);
    (void)b;
    auto s = std::make_unique<State>();
    s->stage_ms.assign(0, 0.0);
    s->matrices.assign(size_t(b.bones) * 16, 0.0f);
    for (uint32_t i = 0; i < b.bones; ++i)
      for (int k = 0; k < 4; ++k) s->matrices[size_t(i) * 16 + k * 5] = 1.0f;
    return s;
  }

  bool update(const runtime::Build &build, runtime::PoseState &state, const void *params, const float *clocks,
              std::string &error) const override {
    const Params &p = *static_cast<const Params *>(params);
    (void)p;
    (void)clocks;
    (void)build;
    (void)state;
    (void)error;
    return true;
  }

  uint64_t pose_hash(const runtime::PoseState &state) const override {
    (void)state;
    return 0;
  }
};

const Type kType;

bool valid(const Params &p) {
  if (static_cast<uint32_t>(p.species) >= 5u) return false;
  if (static_cast<uint32_t>(p.season) >= 4u) return false;
  if (p.variant > 12u) return false;
  if (static_cast<uint32_t>(p.detail) >= 4u) return false;
  if (static_cast<uint32_t>(p.bed) >= 2u) return false;
  if (p.cell_q > 1000u) return false;
  if (p.cell_r > 1000u) return false;
  if (static_cast<uint32_t>(p.ground) >= 5u) return false;
  if (!std::isfinite(p.moisture) || p.moisture < 0.0f || p.moisture > 0x1.0000000000000p+0f) return false;
  if (p.world_seed < 1u || p.world_seed > 1000000u) return false;
  if (!std::isfinite(p.wind_speed) || p.wind_speed < 0.0f || p.wind_speed > 0x1.9000000000000p+4f) return false;
  if (!std::isfinite(p.wind_heading) || p.wind_heading < 0.0f || p.wind_heading > 0x1.6800000000000p+8f) return false;
  return true;
}

