int foundry_grass_species_find(const char *name) {
  static const char *const names[] = {"dune", "lawn", "meadow", "prairie", "sedge"};
  for (int i = 0; name && i < 5; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_grass_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

